const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var nm = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'New Mexico'));
  var geometry = nm.geometry();

  // ERA5-Land dataset for long-term temperature (monthly aggregated)
  var dataset = 'ECMWF/ERA5_LAND/MONTHLY';
  var band = 'temperature_2m';

  // 2. Data Acquisition for 30-year period (1986-2016, July only)
  var years = ee.List.sequence(1986, 2016);
  var julyImages = years.map(function(year) {
    var start = ee.Date.fromYMD(year, 7, 1);
    var end = ee.Date.fromYMD(year, 8, 1);
    return ee.ImageCollection(dataset)
      .filterDate(start, end)
      .select(band)
      .mean()
      .set('year', year);
  });

  var collection = ee.ImageCollection(julyImages);

  // Check collection size
  var size = collection.size().getInfo();
  if (size === 0) {
    print("No data found for any July 1986-2016.");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing: Compute mean temperature for each July
  var stats = collection.map(function(img) {
    var mean = img.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geometry,
      scale: 10000,
      maxPixels: 1e9
    });
    var count = img.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 10000,
      maxPixels: 1e9
    });
    return ee.Feature(null, {
      'year': img.get('year'),
      'temp': mean.get(band),
      'pixels': count.get(band)
    });
  });

  var list = stats.reduceColumns({
    reducer: ee.Reducer.toList(3),
    selectors: ['year', 'temp', 'pixels']
  }).get('list').getInfo();

  // 4. Validation & Calculation
  var temps = [];
  var validYears = [];

  for (var i = 0; i < list.length; i++) {
    var year = list[i][0];
    var temp = list[i][1];
    var pixels = list[i][2];

    if (pixels === 0 || pixels === null) {
      print("Year " + year + ": No valid pixels.");
      print("<answer>C2</answer>");
      return;
    }

    if (temp === null || temp === undefined || Math.abs(temp) > 100) {
      print("Year " + year + ": Invalid temperature: " + temp);
      print("<answer>C3</answer>");
      return;
    }

    temps.push(temp);
    validYears.push(year);
    print(year + ": " + temp.toFixed(2) + "°C (pixels: " + pixels + ")");
  }

  if (validYears.length < 31) {
    print("Missing some years: only " + validYears.length + " valid.");
    print("<answer>C1</answer>");
    return;
  }

  // 5. Comparison: Is 2016 higher than all other years?
  var temp2016 = temps[validYears.indexOf(2016)];
  var otherTemps = temps.filter(function(t, idx) {
    return validYears[idx] !== 2016;
  });

  var maxOther = Math.max.apply(null, otherTemps);

  print("2016 temperature: " + temp2016.toFixed(2) + "°C");
  print("Max other years (1986-2015): " + maxOther.toFixed(2) + "°C");

  if (temp2016 > maxOther) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
